using namespace std;

typedef long long ll;
typedef unsigned long long ull;
typedef pair<int,int> pa;
typedef vector<int> ve;

#define REP(i,a,b) for(int i=a;i<b;i++)
#define rep(i,n) REP(i,0,n)
#define pb push_back
#define inf 1000000000
#define mp make_pair
#define sz size()
#define all(vec) (vec).begin(),(vec).end()

int main()
{
    //freopen("input.txt","r",stdin);
    ll n,a,b;
    cin>>a>>b>>n;
    long double a1=a,b1=b;
    long double ans1=inf;
    long double ter1=a1/b1;
    ll ans2,ans3;
    for(ll i=1;i<=n;i++)
    {
    	ll te1=(a*i)/b;
    	long double te2=te1,te3=i;
    	long double temp1=te2/te3;
    	temp1=temp1-ter1;
    	if(temp1<0)	temp1*=(-1.0);
    	long double temp2=(te2+1.0)/te3;
    	temp2=temp2-ter1;
    	if(temp2<0)	temp2*=(-1.0);
    	if(temp1<ans1 || (temp1==ans1 && (i<ans3 ||(i==ans3 && te1<ans2))))
    	{
    		ans1=temp1;
    		ans3=i;
    		ans2=te1;
    	}
    	if(temp2<ans1 || (temp2==ans2 && (i<ans3 ||(i==ans3 && te1+1<ans2))))
    	{
    		ans1=temp2;
    		ans3=i;
    		ans2=te1+1;
    	}
    	if(te1==0)	continue;
    	temp2=(te2-1.0)/te3;
    	temp2=temp2-ter1;
    	if(temp2<0)	temp2*=(-1.0);
    	if(temp2<ans1 || (temp2==ans2 && (i<ans3 ||(i==ans3 && te1+1<ans2))))
    	{
    		ans1=temp2;
    		ans3=i;
    		ans2=te1-1;
    	}
    }
    cout<<ans2<<"/"<<ans3<<endl;
    return 0;
}
